from __future__ import annotations

from hypothesis import given, strategies

from cloud.services.checkpointer import ResolveInterruptRequest
from cloud.services.checkpointer._resume import (
    edited_resume_values,
    resume_payload_from_records,
)
from cloud.services.checkpointer._types import InterruptRecord


def _record(control_id: str, decision: str, edited: str | None = None) -> InterruptRecord:
    return InterruptRecord(
        run_id="run-resume",
        control_id=control_id,
        reason=f"confirm {control_id}",
        suggested_value=control_id,
        state=decision,
        created_at=1.0,
        resolved_at=2.0,
        decision=decision,
        edited_value=edited,
    )


def test_resume_payload_from_records_integration_keeps_skipped_decisions() -> None:
    records = {
        "field_salary": _record("field_salary", "approved"),
        "field_start_date": _record("field_start_date", "skipped"),
    }

    payload = resume_payload_from_records(
        ResolveInterruptRequest(
            run_id="run-resume",
            control_id="field_start_date",
            decision="skipped",
        ),
        records,
    )

    assert payload == {
        "control_id": "field_start_date",
        "decision": "skipped",
        "edited_value": None,
        "decisions": {
            "field_salary": {"decision": "approved"},
            "field_start_date": {"decision": "skipped"},
        },
        "feedback_type": None,
        "feedback_note": None,
        "feedback_category": None,
        "interrupt_context": {
            "control_type": "review",
            "reason": "confirm field_start_date",
            "suggested_value": "field_start_date",
        },
    }, "resume payload should expose skipped per-control decisions"


@given(strategies.booleans(), strategies.booleans())
def test_edited_resume_values_property_filters_unconsumed_edits(
    include_edit: bool,
    consumed: bool,
) -> None:
    records = {"field": _record("field", "edited", "new value")}
    records["field"].consumed = consumed
    if not include_edit:
        records["field"].decision = "approved"
        records["field"].edited_value = None

    expected = {"field": "new value"} if include_edit and not consumed else {}

    assert edited_resume_values(records) == expected, (
        "edited resume values should include only active edited decisions"
    )

